
  (function(){
    'use strict';
    const references={
      tongue:{
        file:'img/symptoms/tongue.jpg',
        title:'Dilde kızarıklık · görsel örnek',
        text:'Dilde kızarıklık veya pürüzsüzleşme farklı nedenlerle görülebilir. Bu örnek kendi görünümünüzle kesin karşılaştırma veya vitamin eksikliği tanısı için kullanılamaz.',
        alt:'Paylaşılan uygulama örneğinden dil görünümü',
        image:'data:image/jpeg;base64,'
      },
      nails:{
        file:'img/symptoms/nails.jpg',
        title:'Tırnakta beyaz çizgi veya nokta · görsel örnek',
        text:'Tırnaktaki beyaz alanların birçok nedeni olabilir. Görünüm tek başına vitamin veya mineral eksikliği göstermez; yeni ya da değişen tırnak bulguları için sağlık uzmanına danışın.',
        alt:'Paylaşılan uygulama örneğinden tırnak görünümü',
        image:'data:image/jpeg;base64,'
      },
      mouth:{
        file:'img/symptoms/mouth.jpg',
        title:'Dudak köşelerinde çatlak · görsel örnek',
        text:'Ağız köşesi çatlakları tahriş, enfeksiyon veya farklı sağlık/beslenme nedenleriyle görülebilir. Tek başına belirli bir vitamin eksikliğini kanıtlamaz.',
        alt:'Paylaşılan uygulama örneğinden dudak köşesi görünümü',
        image:'data:image/jpeg;base64,'
      },
      rash:{
        file:'img/symptoms/rash.jpg',
        title:'Ciltte kızarıklık veya döküntü · görsel örnek',
        text:'Cilt döküntülerinin çok sayıda nedeni olabilir; bu örnek vitamin eksikliğini göstermez. Yeni, yaygın veya kötüleşen döküntüyü sağlık uzmanına danışın.',
        alt:'Paylaşılan uygulama örneğinden cilt döküntüsü görünümü',
        image:'data:image/jpeg;base64,'
      },
      hair:{
        file:'img/symptoms/hair.jpg',
        title:'Saç dökülmesi · görsel örnek',
        text:'Saç yoğunluğu ve dökülme kişiden kişiye değişir. Fotoğraf tanı ölçütü değildir; saç dökülmesi tek başına vitamin eksikliğini göstermez.',
        alt:'Paylaşılan uygulama örneğinden saç görünümü',
        image:'data:image/jpeg;base64,'
      }
    };
    let modal=null;
    let returnFocus=null;
    let previousOverflow='';
    function ensureModal(){
      if(modal)return modal;
      modal=document.createElement('div');
      modal.className='vita-visual-overlay';
      modal.id='vitaVisualReferenceModal';
      modal.hidden=true;
      modal.setAttribute('role','dialog');
      modal.setAttribute('aria-modal','true');
      modal.setAttribute('aria-labelledby','vitaVisualReferenceTitle');
      modal.innerHTML='<section class="vita-visual-dialog"><div class="flex items-start justify-between gap-3"><div><h2 id="vitaVisualReferenceTitle" class="text-base font-black text-slate-900"></h2><p id="vitaVisualReferenceText" class="mt-2 text-xs leading-relaxed text-slate-600"></p></div><button type="button" class="vita-visual-close shrink-0 rounded-lg border border-slate-200 px-3 py-2 text-slate-700" aria-label="Örnek görünümü kapat">Kapat</button></div><img id="vitaVisualReferenceImage" class="vita-visual-art" alt=""><p id="vitaVisualReferenceFallback" class="hidden rounded-lg border border-slate-200 bg-slate-50 p-3 text-xs text-slate-600"></p><p class="rounded-lg border border-amber-200 bg-amber-50 p-2.5 text-[11px] leading-relaxed text-amber-950"><strong>Önemli:</strong> Bu görsel, paylaşılan uygulama ekranındaki temsili örnektir; tanı kanıtı değildir ve kişisel görünümünüzü değerlendirmez. Belirti tek başına tanı koydurmaz. Belirti sürüyorsa sağlık uzmanına danışın.</p></section>';
      document.body.appendChild(modal);
      const closeButton=modal.querySelector('.vita-visual-close');
      function close(){
        modal.hidden=true;
        document.body.style.overflow=previousOverflow;
        if(returnFocus&&typeof returnFocus.focus==='function')returnFocus.focus();
      }
      closeButton.addEventListener('click',close);
      modal.addEventListener('click',event=>{if(event.target===modal)close();});
      modal.addEventListener('keydown',event=>{
        if(event.key==='Escape'){event.preventDefault();close();return;}
        if(event.key!=='Tab')return;
        const focusable=[...modal.querySelectorAll('button:not([disabled])')];
        if(!focusable.length)return;
        if(event.shiftKey&&document.activeElement===focusable[0]){event.preventDefault();focusable[focusable.length-1].focus();}
        else if(!event.shiftKey&&document.activeElement===focusable[focusable.length-1]){event.preventDefault();focusable[0].focus();}
      });
      return modal;
    }
    window.showVitaVisualReference=function(type,trigger){
      const reference=references[type];
      if(!reference)return;
      const dialog=ensureModal();
      returnFocus=trigger||document.activeElement;
      previousOverflow=document.body.style.overflow;
      dialog.querySelector('#vitaVisualReferenceTitle').textContent=reference.title;
      dialog.querySelector('#vitaVisualReferenceText').textContent=reference.text;
      const image=dialog.querySelector('#vitaVisualReferenceImage');
      const fallback=dialog.querySelector('#vitaVisualReferenceFallback');
      image.hidden=false;
      fallback.hidden=true;
      image.alt=reference.alt;
      const showError=()=>{
        image.hidden=true;
        fallback.textContent='Görsel örnek yüklenemedi. Açıklamayı okuyabilir veya pencereyi kapatabilirsiniz.';
        fallback.hidden=false;
      };
      // Önce img/symptoms/<ad>.jpg dosyası denenir (gerçek fotoğraf konulursa o görünür); yoksa gömülü yedek görsel kullanılır.
      image.onerror=()=>{
        image.onerror=showError;
        image.src=reference.image;
      };
      image.src=reference.file||reference.image;
      dialog.hidden=false;
      document.body.style.overflow='hidden';
      dialog.querySelector('.vita-visual-close').focus();
    };
    document.addEventListener('click',event=>{
      const trigger=event.target.closest('[data-vita-visual]');
      if(!trigger)return;
      event.preventDefault();
      event.stopPropagation();
      window.showVitaVisualReference(trigger.dataset.vitaVisual,trigger);
    });
  })();
  